INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (53, 303, '一些特殊的符号', '../', '<p></p><p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#202124;font-family:arial, sans-serif;background-color:#FFFFFF;">㎡ (square meter)</span><br/> </span></p> <p><span style="font-family:宋体;font-size:10.5pt;">±</span></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;">ºC</span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span>波浪线</span> <span>符号</span> </span><span style="font-family:Arial;font-size:10.5pt;"><span>﹏</span></span></p> <p><u><span style="color:#2200CC;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>用</span>√</span></u><u><span style="color:#CC0033;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>符号</span></span></u><u><span style="color:#2200CC;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>。错用</span>×</span></u><u><span style="color:#CC0033;font-family:Arial;font-size:13.5pt;text-decoration:underline;"><span>符号</span></span></u></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;">Ω</span></p> <p></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;"><span>＜</span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;"><span>＞</span></span></p> <p><span style="color:#000000;font-family:Arial;font-size:10.5pt;">≤<span>、</span><span>≥</span></span></p>', '2026-09-06 20:58:45');
