INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (53, 304, '单位换算 -公制到英制换算', '../', '<p></p><p align="justify" style="text-align:justify;"> 密耳是一个长度的单位，代表千分之一英寸，1mil（密尔）=25.39999918μm（微米）<br/> grammage 1 lb=3.75gsm,1LB=0.453592Kg lb指磅（重量单位） <br/> 1码（yard) = 91.44 厘米<br/> 1英尺(feet) = 0.3048 米 30.5cm<br/></p> <span style=''font-family:"font-size:10.5pt;''> <p align="justify" style="text-align:justify;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span>公制到英制换算</span> </span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Linear Measure </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">长度</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 millimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">毫米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.03937 inch </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 centimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">厘米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=10 mm. </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">毫米</span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">=0.3937 inch </span></span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">英寸</span></span></span></p> <p><span style="font-family:宋体;font-size:10.5pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1 decimetre </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">分米</span></span><span><span style="