INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (53, 421, 'TEAM''S CULTURE', '../', '<p>Guarantees the quality, promotes the efficiency, stresses the integrity , and more self-dedicated of business cooperation ---- which is always educated by Group as the motto of all staffs. Not enjoys the present enormous &amp; well-being wealth, but brings the world more welfare through faith of our own dedicating, hard working and success.</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (53, 422, 'COMPANY’S CULTURE', '../', '<p>&nbsp;<br/> Asia Pacific Company''s Guiding Ideology: Marxism-Leninism, Mao Zedong Thought, Deng Xiaoping Theory and "Three Represents" as guidance, to make a scientific development and innovation.<br/> <br/> Asia Pacific Company''s Business Philosophy: "National industries as cornerstone , Global market-oriented as platform, and Scientific development as road".<br/> &nbsp;<br/> Asia Pacific Company''s business purposes: Global business, dedication and development,harmony together.<br/> <br/> Asia Pacific Company''s guidelines and style of work: Guarantees the quality, promotes the efficiency, stresses the integrity , and more self-dedicated of business cooperation.<br/> <br/> Asia Pacific Company''s work ethics: In pace and calm confidently,Not enjoys the present enormous &amp; well-being wealth, but brings the world more welfare through faith of our own dedicating, hard working and success.<br/></p>', '2026-09-06 20:58:45');